// === Tab: mySketch ===
let colors = [];
let brush = { x:0, y:0, px:0, py:0 }
let seed;
let fakemouseX;
let fakemouseY;

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();
  seed = random(1000);
  colors = [
  color(112,112,74), //green
  color(245,198,110), //yellow
  color(242,229,194), //cream
  color(115,106,97), //light grey
  color(215,90,34), //orange
  color(235,61,0)] // red-orange
  let base = floor(random(colors.length));
  background(0);
  colors.splice(base,1);
}

function draw() {
    fakemouseX=frameCount*sin((random(-30,30)+frameCount)/100)+(random(100)); //
  fakemouseX=fakemouseX % width;
    fakemouseY=frameCount*cos(frameCount/100)+(random(100));
  fakemouseY=fakemouseY % height;
  brush.x+=(width/3+fakemouseX-brush.x)/12;
  brush.y+=(height/3+fakemouseY-brush.y)/12;
  if(frameCount>40){
    drizzle();
  }
  brush.px=brush.x;
   brush.py=brush.y;
}


function mouseMoved(){
  if(frameCount%7==0){
    splatter(fakemouseX, fakemouseY);
    splatter(width-fakemouseX, height-fakemouseY);
    stipple(fakemouseX, fakemouseY, 0);
    stipple(width-fakemouseX, height-fakemouseY, 255);
  }
}

function drizzle(){
  let s = 1+30/dist(brush.px, brush.py, brush.x, brush.y);
  s=(min(12,s)+s)/2+5;
  strokeWeight(s); //粗细
  stroke(245,198,110);//轮廓蓝
  line(brush.px, brush.py, brush.x, brush.y);// line(x1,y1,x2,y2)
  stroke(40,130,205);//轮廓黄
  line(width-brush.px, height-brush.py, width-brush.x, height-brush.y);


    if(frameCount%7==0){
    splatter(fakemouseX % width, fakemouseY % height);
    splatter(width-fakemouseX, height-fakemouseY);
    stipple(fakemouseX % width,  fakemouseY % height, 0);
    stipple(width-fakemouseX, height-fakemouseY, 255);
  }


}


function splatter(bx,by){
  let c = colors[floor(random(colors.length))];
  bx += random(-15,15);
  by += random(-15,15);//波动远近范围
  let mx = 10*fakemouseX;
  let my = 10*fakemouseY;
  for(let i=0; i<80; i++){
    seed+=.1;
    let x = bx+mx*(0.5-noise(seed+i));
    let y = by+my*(0.5-noise(seed+2*i));
    var s = 150/dist(bx, by, x, y);
    if(s>20) s=20;
    let a = 255-s*5;
    noStroke();
    c.setAlpha(a);
    fill(c);//填充颜色
    ellipse(x,y,s);//圆形
    seed+=.01;
  }
}

function stipple(bx, by, c){
  noStroke();
  fill(c);
  let radius = random(3, 12);
  ellipse(bx+random(-30,windowWidth-bx), by+random(30,windowHeight-by), radius);
  radius = random(3, 12);
  ellipse(bx+random(-30,windowWidth-bx), by+random(30,windowWidth-by), radius);
}


function keyPressed(){
  if(keyCode==32){
    background(180);
  }
}

